//! Native modules of a TS + TSX app: the runtime side of the `native/` bridge
//! (the code generator is `zant-tsx::native_specs`).
//!
//! Each `native/<name>.rs` is checked against its spec (`native/<name>.ts`)
//! at compile time: every function the spec declares has to exist with
//! exactly that signature. The type system does the checking: `zant-tsx` generates one trait per spec from the `.ts`
//! file, the app writes `impl ClipSpec for Native`, and a missing or mistyped
//! function is a rustc error at the `impl`:
//!
//! ```ignore
//! // native/spec.rs (generated by zant-tsx)
//! pub mod clip {
//!     pub trait ClipSpec {
//!         fn list() -> zant::tsx::List<Clip>;
//!     }
//!     pub const NAME: &str = "clip";
//! }
//!
//! // native/clip.rs (the app)
//! pub struct Native;
//! impl crate::native::spec::clip::ClipSpec for Native {
//!     fn list() -> zant::tsx::List<Clip> { /* .. */ }
//! }
//!
//! // generated call site of `invoke.list()`
//! <crate::native::clip::Native as crate::native::spec::clip::ClipSpec>::list()
//!
//! // generated entry, once at startup
//! zant::tsx::native::register_named(
//!     crate::native::spec::clip::NAME,
//!     crate::native::clip::Native,
//! );
//! ```
//!
//! What is left for the runtime is the **registry** the generated entry uses
//! when a module is resolved by name (the `invoke` namespace, tests that swap
//! an implementation, and native modules registered by the app instead of
//! generated): implementations register themselves under the spec's generated
//! `NAME` and are fetched with a type check. [`NativeModule`] is the
//! hand-written convenience shape (a single associated `NAME`); the generated
//! specs pass their module-level `NAME` to [`register_named`] instead.
//!
//! ```ignore
//! tsx::native::register_named(clip::NAME, Native);
//! let native = tsx::native::get_named::<Native>(clip::NAME).expect("registered");
//! ```
//!
//! The registry is optional overhead: the
//! static call path (the generated one) never touches it.

use std::any::Any;
use std::cell::RefCell;
use std::collections::HashMap;
use std::rc::Rc;

/// A native module implementation (`native/<name>.rs`): the module name is the
/// `.ts` spec's file stem.
pub trait NativeModule: 'static {
    /// `native/<NAME>.ts` / `native/<NAME>.rs`.
    const NAME: &'static str;
}

thread_local! {
    /// Registered implementations of this UI thread, by module name.
    static MODULES: RefCell<HashMap<&'static str, Rc<dyn Any>>> =
        RefCell::new(HashMap::new());
}

/// Registers `module` under its [`NativeModule::NAME`]; false when that name
/// is already taken (the first registration wins, like one module per spec).
pub fn register<T: NativeModule>(module: T) -> bool {
    register_named(T::NAME, module)
}

/// Registers `module` under `name` — the `NAME` of a generated spec
/// (`crate::native::spec::<name>::NAME`), so the generated entry needs
/// no [`NativeModule`] impl next to the spec's trait impl. False when that
/// name is already taken.
pub fn register_named<T: 'static>(name: &'static str, module: T) -> bool {
    MODULES.with(|modules| {
        let mut modules = modules.borrow_mut();
        if modules.contains_key(name) {
            return false;
        }
        let value: Rc<dyn Any> = Rc::new(module);
        modules.insert(name, value);
        true
    })
}

/// The registered implementation of `name`, downcast to `T`; `None` when the
/// name is unknown or holds another type.
pub fn get<T: 'static>(name: &str) -> Option<Rc<T>> {
    get_named::<T>(name)
}

/// [`get`] under an explicit name: the generated specs' registry key.
pub fn get_named<T: 'static>(name: &str) -> Option<Rc<T>> {
    MODULES.with(|modules| {
        let modules = modules.borrow();
        let value = modules.get(name)?;
        Rc::clone(value).downcast::<T>().ok()
    })
}

/// Whether a module is registered under `name`.
pub fn registered(name: &str) -> bool {
    MODULES.with(|modules| modules.borrow().contains_key(name))
}

/// Forgets every registration (tests, or an app restart in the same process).
pub fn clear() {
    let modules = MODULES.with(|modules| std::mem::take(&mut *modules.borrow_mut()));
    drop(modules);
}

#[cfg(test)]
mod tests {
    use super::*;

    trait Doubler: 'static {
        fn twice(&self, n: i64) -> i64;
    }

    struct Demo {
        base: i64,
    }

    impl NativeModule for Demo {
        const NAME: &'static str = "demo";
    }

    impl Doubler for Demo {
        fn twice(&self, n: i64) -> i64 {
            self.base + n * 2
        }
    }

    #[test]
    fn a_registered_module_is_fetched_by_name_with_its_type() {
        clear();
        assert!(!registered("demo"));
        assert!(register(Demo { base: 0 }));
        assert!(registered("demo"));
        assert!(!register(Demo { base: 1 }), "the first registration wins");
        let module = get::<Demo>("demo").expect("registered");
        assert_eq!(module.twice(2), 4);
        // the same object through the trait object of its spec
        let as_trait: Rc<dyn Doubler> = module;
        assert_eq!(as_trait.twice(3), 6);
        assert!(get::<String>("demo").is_none(), "wrong type: None");
        assert!(get::<Demo>("missing").is_none());
        clear();
        assert!(get::<Demo>("demo").is_none());
    }

    #[test]
    fn a_generated_spec_name_registers_without_a_native_module_impl() {
        struct Clip {
            base: i64,
        }

        impl Clip {
            fn twice(&self, n: i64) -> i64 {
                self.base + n * 2
            }
        }

        clear();
        // `zant-tsx` generates a module-level `NAME`; the app only implements
        // the spec's trait (no `NativeModule` impl needed).
        const NAME: &str = "clip";
        assert!(register_named(NAME, Clip { base: 1 }));
        assert!(registered("clip"));
        assert!(!register_named(NAME, Clip { base: 2 }));
        let module = get_named::<Clip>(NAME).expect("registered");
        assert_eq!(module.twice(2), 5);
        assert!(get_named::<String>("clip").is_none());
        assert!(!registered("demo"), "registrations are per name");
        clear();
    }
}
